for d in departments:
    did = d['id']
    dept_emps = [e for e in employees if e['department_id'] == did]
    emp_objs = []
    for e in dept_emps:
        skills = [s.strip() for s in e['skills'].split(';') if s.strip()]
        emp_objs.append({
            'id': e['id'],
            'name': e['name'],
            'position': e['position'],
            'skills': skills,
            'years_of_service': int(e['years_of_service']),
        })
    dept_projs = [p for p in projects if p['department_id'] == did]
    proj_objs = []
    for p in dept_projs:
        members = [m.strip() for m in p['member_ids'].split(';') if m.strip()]
        proj_objs.append({
            'name': p['name'],
            'status': p['status'],
            'members': members,
            'deadline': p['deadline'],
        })
    dept_list.append({
        'id': d['id'],
        'name': d['name'],
        'budget': float(d['budget']),
        'employees': emp_objs,
        'projects': proj_objs,
    })

# statistics
total_employees = len(employees)
years = [int(e['years_of_service']) for e in employees]
avg_years = sum(years) / len(years) if years else 0

budgets = [float(d['budget']) for d in departments]
avg_budget = sum(budgets) / len(budgets) if budgets else 0

